  "implementation": "def solve(case):
    import math
    sentence_vectors = case['sentence_vectors']
    query_vector = case['query_vector']
    context_weight = case['context_weight']
    n = len(sentence_vectors)
    if n == 0:
        return []
    dim = len(query_vector)
    context = [0.0] * dim
    for sv in sentence_vectors:
        for i in range(dim):
            context[i] += sv[i]
    context = [x / n for x in context]
    def dot(u, v):
        return sum(ui * vi for ui, vi in zip(u, v))
    def norm(v):
        return math.sqrt(dot(v, v))
    q_norm = norm(query_vector)
    c_norm = norm(context)
    scores = []
    for sv in sentence_vectors:
        sv_norm = norm(sv)
        sim_q = dot(query_vector, sv) / (q_norm * sv_norm) if q_norm and sv_norm else 0.0
        sim_c = dot(context, sv) / (c_norm * sv_norm) if c_norm and sv_norm else 0.0
        score = (1 - context_weight) * sim_q + context_weight * sim_c
        scores.append(score)
    return scores"
